INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_5e355d03f6eb6a4e866ead', 'DD publishing model: ground rules', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "robert@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'DD publishing model: ground rules\nWritten for next Monday''s talk. Leonard, Sep 29.\n\nWho''s in\nEvery publisher on Fred''s outreach sheet, plus any publisher that came to one of the four of us about Domino Delights since Apr 1, 2025, however it reached us. A name someone passed along doesn''t count unless they came to us. Co-dev, engine or investment talks aren''t part of this, even where DD came up. That covers Homa and NCsoft, and Fred''s UA funding form to Tilting Point.\n\nStatus (first that fits, top to bottom)\nWithdrawn: they gave terms, then took them back.\nOut on rights: their terms take something we keep. The position from the August sync still stands.\nLive: a rev share and an advance in writing from them, whether that''s a term sheet, an email, or their note pasted in by one of us.\nPassed: they said no.\nWaiting on us: they wrote to us, there are no terms, and the last message is theirs.\nNo reply: nothing back from them. An automatic acknowledgement doesn''t count.\n\nUse the latest terms we have from them, wherever they are, calls included.\n\nValuing a Live offer\nMonthly installs x 12 x $0.50 is the gross. $0.50 is the organic D30 ARPI from my Sep 24 note. It''s a planning figure, not a promise.\nOur share is the rev share they offer us times the gross.\n12-month value is the larger of our share and the total advance, because the advance is recouped out of our share.\n\nQ4 cash\nAdvance money that lands between Oct 1 and Dec 31, 2025. Assume we sign on Oct 31. If our lawyers give us a later date, use theirs. A payment on net terms lands that many days after signature. Rev share statements don''t land in Q4. Banked means it''s actually in the SVB account.\n\nKeep value\nWhat DD earned in Jul, Aug and Sep (ANALYTICS.MONETIZATION.REVENUE_DAILY, total_revenue_usd), averaged, times 12.\n\nFirst pick\nThe Live offer with the highest 12-month value.\n\nReminders\nOne for each Live offer on Fred''s calendar, on its response date, named for the publisher.\n\nLayout\nA Google Sheet called DD publishing model. Tab Publishers: Publisher, Status, Advance, Monthly installs, 12-month value, Q4 cash. Figures only for Live offers. Tab Summary: Keep value, First pick, Banked so far.\n\nAnything I''ve already said about what goes out to publishers still applies.', '[{"start": 0, "end": 34, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 34, "end": 84, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 84, "end": 93, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 93, "end": 473, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 473, "end": 513, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 513, "end": 1055, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1055, "end": 1076, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1076, "end": 1384, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1384, "end": 1392, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1392, "end": 1672, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1672, "end": 1683, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1683, "end": 1798, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1798, "end": 1809, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1809, "end": 1858, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1858, "end": 1868, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1868, "end": 1960, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1960, "end": 1967, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1967, "end": 2255, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '352eb5f6b8', 'f_5e355d03f6eb6a4e866ead', '2025-09-29T16:00:00Z', '2025-09-29T16:00:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_21203dbcdf780cc07c76cb', 'Co-dev: what we''d take', 'frederick.stone@harmonygames.co', '["leonard.hayes@harmonygames.co"]', 'private', E'Co-dev: what we''d take\nFred, Sep 19. For the co-dev talks only, not DD.\nThey fund a team of 6 to 10 for a fixed term.\nMilestones paid monthly, not on launch.\nWe keep the engine and the IP in the game.\nA 50/50 net split after they recoup the dev spend is the starting point.', '[{"start": 0, "end": 23, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 23, "end": 273, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '3ce8ed2bdd', 'f_21203dbcdf780cc07c76cb', '2025-09-19T17:30:00Z', '2025-09-19T17:30:00Z');
