VALUES ('f_27cac0eed300cc33eeb4fd', 'Oakline Games - term sheet - Domino Delights', 'marek@oaklinegames.com', '["frederick.stone@harmonygames.co"]', 'private', E'Oakline Games - term sheet - Domino Delights\nTerms for Harmony Games\n30% of net to Harmony Games\n$30,000 advance ($10,000 first-look payment within 5 days of this sheet, credited to the advance, the remaining $20,000 net 30 from signature)\n20,000 installs a month for 12 months\nMobile stores\nRespond by Oct 24\nMarek Sobol, Oakline Games', '[{"start": 0, "end": 45, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 45, "end": 336, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '588b35f222', 'f_27cac0eed300cc33eeb4fd', '2025-09-25T15:30:00Z', '2025-09-25T15:30:00Z');
