INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('bda432db3ac81bf7f0c8903f0465ec9d', '1757090400.829462', 'D05S58U4SAK', 'message', 'EMPLOYEE_0008_SLACK_ID', 'Couldn''t find anyone from Rayking on LinkedIn. Parking it for now, we still owe them an answer.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-05T16:40:00.829462Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('f55bd27436eb285a15d833648b922e9b', '1758915000.867092', 'C096HFA5Z8W', 'message', 'EMPLOYEE_0038_SLACK_ID', 'On the numbers going out: the May one-pager only had the paid-traffic numbers on it. Anyone who got it and still has an offer in with us hears the organic figure from us, $0.50 D30 ARPI, before we go any further with them. Fred, one short note each, left in your Gmail drafts, and I''ll read them with you first.', '0f6848b39af117c741af520ce5204eac', '1758147530.732569', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-26T19:30:00.867092Z', '{}');
UPDATE slack.slack_messages SET reply_count = 5, reply_users_count = 2, latest_reply = '1758915000.867092' WHERE id = '0f6848b39af117c741af520ce5204eac';
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('495d71a7e14dfaa68cac26fc4a6c4e03', '1758909900.662794', 'C07C2866011', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Off topic but I''m in here anyway: someone I know at Copperleaf Games, a small publisher, saw DD and emailed me out of the blue: "We''d do 28% of net to you, a $32,000 advance net 30 from signature, 40,000 installs a month for 12 months, mobile stores only, respond by Oct 17. Jonas Weber, Copperleaf, jonas@copperleafgames.com"', 'aaec7171d897e134a22b41511467f646', '1758736960.824899', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-26T18:05:00.662794Z', '{}');
UPDATE slack.slack_messages SET reply_count = 9, reply_users_count = 1, latest_reply = '1758909900.662794' WHERE id = 'aaec7171d897e134a22b41511467f646';
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('e64606893af9f4316891a357ec26a691', '1758912000.686342', 'C069FF9Q57S', 'message', 'EMPLOYEE_0025_SLACK_ID', 'A tech lead at a publisher asked me about Singular deep links for DD. Notes are on ENG-2362.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-26T18:40:00.686342Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('e44da6a468e7795a1b5853cfb0763aaf', '1759176900.065118', 'C07C2866011', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Got a call from Kestrel. They''ve frozen every outside signing for the year, so whatever they had on the table with us is off.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-29T20:15:00.065118Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('0230b2df24ec829928fe1c55ad6185bf', '1759251900.005166', 'C07C2866011', 'message', 'EMPLOYEE_0025_SLACK_ID', 'Checked SVB with Leonard this morning: that $10K first-look never hit the account. Their bank sent it back because they put Calm Play as the beneficiary and the account is in Harmony Games'' name. They''re resending it next week, so it''ll land in October.', '330b95fd38236b4e7192e24f272685b4', '1757345405.134829', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T17:05:00.005166Z', '{}');
UPDATE slack.slack_messages SET reply_count = 3, reply_users_count = 3, latest_reply = '1759251900.005166' WHERE id = '330b95fd38236b4e7192e24f272685b4';
