VALUES ('68dab660c900179df4f5f92d', 'DD publishing', '66da196af476ab78deaa0cef', '670015c2ecd45b634d5eec81', 'For Monday. One checklist per status on this card, one item per publisher. Every Live, Waiting on us and No reply publisher gets a follow-up card on this list, named F/up with plus the publisher''s name. If they already have a card here, leave a comment with the status on that one instead. Leave a one-line nudge to every No reply publisher in your Gmail drafts so it''s ready to send.', 114688.0, false, NULL, false, '["PERSON_6094_TRELLO_USER_ID", "4b4a68fc0fec0b254e4f9d8e"]', '[]', 43, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/Dp3nVx8K/43-dd-publishing', '2025-09-29T16:40:00Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 0, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
