INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('frederick.stone@harmonygames.co/<CAY2swo8Vt78l2VvRPI7Ywn-45Te8GyWBcazV7hy@mail.gmail.com>', 'frederick.stone@harmonygames.co/1844732284109533347', 'frederick.stone@harmonygames.co', '["INBOX", "CATEGORY_PERSONAL"]', 'Fred, a16z didn''t happen and the Turkish fund is a no, so DD publishing, the idea from the sync, is where my head is now. On Monday Oct 6 I ', 1759273800000, '2025-09-30T23:10:00Z', 1866, 'DD publishing: what I need for Monday', 'leonard.hayes@harmonygames.co', 'Leonard Hayes', '["Frederick Stone <frederick.stone@harmonygames.co>"]', '[]', '[]', '[]', E'Fred,\r\n\r\na16z didn''t happen and the Turkish fund is a no, so DD publishing, the idea from the sync, is where my head is now. On Monday Oct 6 I want the four of us to sit down knowing what each publisher would actually bring in. Can you build the model for that?\r\n\r\nThe ground rules doc has how we''re doing this, including who counts and how an offer gets valued. Put the model in your DD publishing folder, laid out the way the doc says.\r\n\r\nDo what''s on the DD publishing card on the UA/BD board too.\r\n\r\nEveryone at a publisher who has given us terms or told us no should be in Contacts, with the company in the job title. Skip anyone who''s already there.\r\n\r\nThat guy from Sep 24 I said I''d chase only wants hypercasual and never made it onto your sheet, so leave him out.\r\n\r\nWhen it''s all in, reply here with which offer goes first, what it brings in over 12 months, what it brings in during Q4, and how much publisher money we''ve actually banked so far.\r\n\r\nLeonard', NULL, '[{"name": "Message-ID", "value": "<CAY2swo8Vt78l2VvRPI7Ywn-45Te8GyWBcazV7hy@mail.gmail.com>"}, {"name": "Date", "value": "Tue, 30 Sep 2025 23:10:00 +0000"}, {"name": "Subject", "value": "DD publishing: what I need for Monday"}, {"name": "From", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}, {"name": "To", "value": "Frederick Stone <frederick.stone@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
