VALUES ('evt_43fda04cd11b9d58a05161', 'frederick.stone@harmonygames.co', 'Tallwater follow-up', 'Agenda: walk through their term sheet, the UA plan for the first two quarters, who runs live ops after launch, and what they need from us on store listings and analytics access. Notes: Paola came back on the call. The advance is $40,000 now, not the number in the term sheet. Everything else stands.', NULL, '2025-09-29T18:30:00Z', '2025-09-29T19:00:00Z', '{"dateTime": "2025-09-29T18:30:00Z"}', '{"dateTime": "2025-09-29T19:00:00Z"}', 'leonard.hayes@harmonygames.co', 'leonard.hayes@harmonygames.co', '[{"email": "frederick.stone@harmonygames.co", "organizer": false, "responseStatus": "accepted", "self": true}, {"email": "leonard.hayes@harmonygames.co", "organizer": true, "responseStatus": "accepted"}, {"email": "paola@tallwatergames.com", "organizer": false, "responseStatus": "needsAction"}]', 'confirmed', NULL, 'opaque', '[]', NULL, NULL, 0, '2025-09-26T17:00:00Z', '2025-09-29T20:00:00Z', 'https://meet.google.com/tqw-hrnd-mzx?hs=224', '350f706db41326720702d19dfc5c54ee@hg4');
