INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('lc_674982ffdca63f854ec6f591', 'ENG-2362', 'usr_cc3e90160f490686', NULL, 'Redwood Arcade''s tech lead, Mei Tanaka (mei@redwoodarcade.com), emailed me about deep links while they look at DD, and put their offer at the bottom for whoever handles this. Pasting it here for the record: "We''d do 24% of net to HG, a $25,000 advance net 45 from signature, 40,000 installs a month for 12 months, mobile stores only, respond by Oct 31. Mei Tanaka, Redwood Arcade"', false, '2025-09-26T18:32:00Z', '2025-09-26T18:32:00Z', 1);
UPDATE linear.linear_issues SET updated_at = '2025-09-26T18:32:00Z' WHERE id = 'ENG-2362';
